export const stockPickerJs = "(() => {                                             \n\n                                                                                                                                                                                                                     \n/** Pure retrieval shared by the browser picker and agent. Captions are searchable, never proof of inspection. */\nfunction searchStock(items             , query             = {})              {\n  const words = (query.text || \"\").toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 2);\n  const scored = items.filter(item => {\n    if (item.status === \"excluded\" || item.status === \"staged\") return false;\n    if (query.kind && item.kind !== query.kind) return false;\n    if (query.minWidth && (!item.width || item.width < query.minWidth)) return false;\n    if (query.industry && !(item.inspection?.industries || item.categories).includes(query.industry)) return false;\n    if (query.role && !(item.inspection?.roles || item.categories).includes(query.role)) return false;\n    if (query.negativeSpace && !item.inspection?.negativeSpace.includes(query.negativeSpace)) return false;\n    const ratio = item.width && item.height ? item.width / item.height : 0;\n    if (query.orientation && (!ratio || (query.orientation === \"landscape\" ? ratio < 1.15 : query.orientation === \"portrait\" ? ratio > 0.87 : ratio < 0.87 || ratio > 1.15))) return false;\n    return true;\n  }).map(item => {\n    const text = JSON.stringify([item.alt, item.tags, item.categories, item.inspection]).toLowerCase();\n    return { item, score: words.reduce((n, word) => n + Number(text.includes(word)), 0) };\n  }).filter(row => !words.length || row.score > 0);\n  return scored.sort((a, b) => b.score - a.score || a.item.id.localeCompare(b.item.id)).slice(0, Math.max(0, Math.min(query.limit ?? 100, 500))).map(row => row.item);\n}\n\nwindow.VitrisStockSearch = searchStock; })();\n(() => {\n  const existing = window.VitrisStock;\n  const state = {\n    catalog: existing?.catalog || { version: 1, items: [] },\n    base: existing?.base || \"\",\n    kind: \"image\",\n    query: \"\",\n    category: \"all\",\n    role: \"\", orientation: \"\", negativeSpace: \"\",\n    onSelect: null,\n  };\n\n  function resolve(path) {\n    if (!path) return \"\";\n    if (/^https?:/i.test(path) || path.startsWith(\"data:\")) return path;\n    const rel = path.replace(/^\\//, \"\");\n    if (state.base) {\n      const base = state.base.endsWith(\"/\") ? state.base : `${state.base}/`;\n      return new URL(rel, base).href;\n    }\n    if (location.protocol === \"file:\" || /\\.html?$/i.test(location.pathname)) {\n      return new URL(rel, new URL(\".\", location.href)).href;\n    }\n    return `${location.origin}/${rel}`;\n  }\n\n  function ensureDialog() {\n    let dialog = document.querySelector(\".stock-dialog\");\n    if (dialog) return dialog;\n    dialog = document.createElement(\"dialog\");\n    dialog.className = \"stock-dialog\";\n    dialog.innerHTML = `<form method=\"dialog\" class=\"stock-dialog__bar\">\n        <input type=\"search\" name=\"q\" placeholder=\"Search the stock library\" aria-label=\"Search stock\">\n        <button type=\"submit\" value=\"close\">Close</button>\n      </form>\n      <div class=\"stock-filters\">\n        <label>Use <select name=\"role\"><option value=\"\">Any</option><option>hero</option><option>context</option><option>detail</option><option>atmosphere</option></select></label>\n        <label>Shape <select name=\"orientation\"><option value=\"\">Any</option><option>landscape</option><option>portrait</option><option>square</option></select></label>\n        <label>Text space <select name=\"negativeSpace\"><option value=\"\">Any</option><option>left</option><option>right</option><option>top</option><option>all</option></select></label>\n      </div>\n      <div class=\"stock-chips\" role=\"tablist\" aria-label=\"Categories\"></div>\n      <div class=\"stock-grid\"></div>`;\n    document.body.append(dialog);\n    dialog.querySelector(\"input[name=q]\").addEventListener(\"input\", (event) => {\n      state.query = event.target.value.trim().toLowerCase();\n      paint();\n    });\n    for (const select of dialog.querySelectorAll(\"select\")) select.addEventListener(\"change\", () => { state[select.name] = select.value; paint(); });\n    return dialog;\n  }\n\n  function items() {\n    if (window.VitrisStockSearch) return window.VitrisStockSearch(state.catalog.items || [], {text: state.query, kind: state.kind, industry: state.category === \"all\" ? undefined : state.category, role: state.role || undefined, orientation: state.orientation || undefined, negativeSpace: state.negativeSpace || undefined});\n    const q = state.query;\n    return (state.catalog.items || []).filter((item) => {\n      if (state.kind && item.kind !== state.kind) return false;\n      if (state.category !== \"all\" && !(item.categories || []).includes(state.category)) return false;\n      if (!q) return true;\n      const blob = `${item.alt} ${item.id} ${(item.tags || []).join(\" \")} ${(item.categories || []).join(\" \")}`.toLowerCase();\n      return blob.includes(q);\n    });\n  }\n\n  function paint() {\n    const dialog = ensureDialog();\n    const chips = dialog.querySelector(\".stock-chips\");\n    const grid = dialog.querySelector(\".stock-grid\");\n    const cats = new Set([\"all\"]);\n    for (const item of state.catalog.items || []) {\n      if (state.kind && item.kind !== state.kind) continue;\n      if (item.status === \"excluded\" || item.status === \"staged\") continue;\n      for (const cat of item.inspection?.industries || item.categories || []) cats.add(cat);\n    }\n    chips.replaceChildren(\n      ...[...cats].map((cat) => {\n        const btn = document.createElement(\"button\");\n        btn.type = \"button\";\n        btn.textContent = cat;\n        btn.setAttribute(\"aria-pressed\", String(cat === state.category));\n        btn.addEventListener(\"click\", () => {\n          state.category = cat;\n          paint();\n        });\n        return btn;\n      }),\n    );\n    const rows = items();\n    if (!rows.length) {\n      grid.innerHTML = `<p class=\"stock-empty\">No matching stock yet. Run <code>npm run stock</code> with a Pexels API key to fill the library.</p>`;\n      return;\n    }\n    grid.replaceChildren(\n      ...rows.map((item) => {\n        const btn = document.createElement(\"button\");\n        btn.type = \"button\";\n        btn.className = \"stock-card\";\n        const media = document.createElement(item.kind === \"video\" ? \"video\" : \"img\");\n        media.src = resolve(item.kind === \"video\" ? item.src : item.thumb || item.src);\n        media.alt = item.alt || \"\";\n        if (item.kind === \"video\") {\n          media.muted = true;\n          media.loop = true;\n          media.playsInline = true;\n          media.poster = resolve(item.thumb); media.preload = \"none\";\n          btn.addEventListener(\"pointerenter\", () => { if (!matchMedia(\"(prefers-reduced-motion: reduce)\").matches) media.play().catch(() => {}); });\n          btn.addEventListener(\"pointerleave\", () => media.pause());\n        }\n        const cap = document.createElement(\"span\");\n        cap.textContent = item.inspection?.description || item.alt || item.id;\n        btn.append(media, cap);\n        btn.addEventListener(\"click\", () => {\n          state.onSelect?.(item.src, item);\n          dialog.close();\n        });\n        return btn;\n      }),\n    );\n  }\n\n  async function load() {\n    // Prefer the published catalog; the embedded copy is the offline fallback.\n    try {\n      const res = await fetch(`${state.base.replace(/\\/$/, \"\")}/stock/catalog.json`, { credentials: \"same-origin\" });\n      if (res.ok) state.catalog = await res.json();\n    } catch {\n      /* gallery may embed the catalog instead */\n    }\n  }\n\n  window.VitrisStock = {\n    get catalog() {\n      return state.catalog;\n    },\n    set catalog(value) {\n      state.catalog = value || { version: 1, items: [] };\n    },\n    get base() {\n      return state.base;\n    },\n    set base(value) {\n      state.base = value || \"\";\n    },\n    resolve,\n    async open(opts) {\n      state.kind = opts?.kind === \"video\" ? \"video\" : \"image\";\n      state.category = \"all\";\n      state.role = \"\"; state.orientation = \"\"; state.negativeSpace = \"\";\n      state.query = \"\";\n      state.onSelect = opts?.onSelect || null;\n      await load();\n      const dialog = ensureDialog();\n      const search = dialog.querySelector(\"input[name=q]\");\n      for (const select of dialog.querySelectorAll(\"select\")) select.value = \"\";\n      search.value = \"\";\n      paint();\n      if (typeof dialog.showModal === \"function\") dialog.showModal();\n      else dialog.setAttribute(\"open\", \"\");\n      search.focus();\n    },\n    bind(root) {\n      (root || document).addEventListener(\"click\", (event) => {\n        const btn = event.target.closest(\"[data-stock-open]\");\n        if (!btn) return;\n        event.preventDefault();\n        const wrap = btn.closest(\".stock-field\") || btn.parentElement;\n        const input = wrap?.querySelector(\"input, textarea\");\n        const kind = btn.getAttribute(\"data-stock-kind\") || input?.dataset.stockKind || \"image\";\n        window.VitrisStock.open({\n          kind,\n          onSelect(url, item) {\n            if (!input) return;\n            input.value = url;\n            input.dispatchEvent(new Event(\"input\", { bubbles: true }));\n            input.dispatchEvent(new Event(\"change\", { bubbles: true }));\n            const thumb = wrap.querySelector(\".stock-thumb\");\n            if (thumb) {\n              thumb.src = item?.thumb ? resolve(item.thumb) : url;\n              thumb.hidden = !thumb.src;\n            }\n          },\n        });\n      });\n    },\n  };\n\n  if (document.readyState === \"loading\") {\n    document.addEventListener(\"DOMContentLoaded\", () => window.VitrisStock.bind(document), { once: true });\n  } else {\n    window.VitrisStock.bind(document);\n  }\n})();\n";
export const stockPickerCss = ".stock-dialog {\n  width: min(56rem, calc(100% - 1.5rem));\n  max-height: min(42rem, calc(100% - 2rem));\n  padding: 0;\n  border: 1px solid var(--color-border, var(--admin-line, #d7e4e8));\n  border-radius: 12px;\n  background: var(--color-surface, var(--admin-surface, #fff));\n  color: var(--color-text, var(--admin-text, #164e63));\n  box-shadow: 0 24px 64px color-mix(in srgb, #000 18%, transparent);\n}\n.stock-dialog::backdrop {\n  background: color-mix(in srgb, #000 45%, transparent);\n}\n.stock-dialog__bar {\n  display: flex;\n  gap: 0.5rem;\n  align-items: center;\n  padding: 0.75rem 0.85rem;\n  border-bottom: 1px solid var(--color-border, var(--admin-line, #d7e4e8));\n}\n.stock-dialog__bar input {\n  flex: 1;\n  font: inherit;\n  min-height: 2.4rem;\n  padding: 0.4rem 0.65rem;\n  border: 1px solid var(--color-border, var(--admin-line, #d7e4e8));\n  border-radius: 8px;\n  background: var(--color-bg, var(--admin-bg, #f4f7f8));\n  color: inherit;\n}\n.stock-dialog__bar button,\n.stock-row button {\n  font: inherit;\n  cursor: pointer;\n  border: 1px solid var(--color-border, var(--admin-line, #d7e4e8));\n  background: var(--color-bg, var(--admin-bg, #f4f7f8));\n  color: inherit;\n  border-radius: 8px;\n  padding: 0.35rem 0.65rem;\n}\n.stock-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.35rem;\n  padding: 0.65rem 0.85rem 0;\n}\n.stock-chips button {\n  font: inherit;\n  font-size: 0.78rem;\n  cursor: pointer;\n  border: 1px solid var(--color-border, var(--admin-line, #d7e4e8));\n  background: transparent;\n  color: inherit;\n  border-radius: 999px;\n  padding: 0.2rem 0.65rem;\n}\n.stock-chips button[aria-pressed=\"true\"] {\n  background: var(--color-text, var(--admin-text, #164e63));\n  color: var(--color-bg, #fff);\n  border-color: transparent;\n}\n.stock-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(8.5rem, 1fr));\n  gap: 0.55rem;\n  padding: 0.85rem;\n  overflow: auto;\n  max-height: 28rem;\n}\n.stock-card {\n  display: grid;\n  gap: 0.3rem;\n  border: 0;\n  padding: 0;\n  background: transparent;\n  color: inherit;\n  text-align: left;\n  cursor: pointer;\n  font: inherit;\n}\n.stock-card img,\n.stock-card video {\n  width: 100%;\n  aspect-ratio: 4 / 3;\n  object-fit: cover;\n  border-radius: 8px;\n  background: var(--color-bg, var(--admin-bg, #ece8e1));\n  border: 1px solid var(--color-border, var(--admin-line, #d7e4e8));\n  font-size: 0;\n  color: transparent;\n}\n.stock-card span {\n  font-size: 0.72rem;\n  line-height: 1.3;\n  color: var(--color-muted, var(--admin-muted, #3d6570));\n}\n.stock-empty {\n  padding: 2rem 1rem;\n  text-align: center;\n  color: var(--color-muted, var(--admin-muted, #3d6570));\n}\n.stock-row {\n  display: flex;\n  gap: 0.4rem;\n  align-items: center;\n}\n.stock-row input { flex: 1; min-width: 0; }\n.stock-thumb {\n  width: 2.75rem;\n  height: 2.75rem;\n  object-fit: cover;\n  border-radius: 6px;\n  border: 1px solid var(--color-border, var(--admin-line, #d7e4e8));\n  background: var(--color-bg, var(--admin-bg, #f4f7f8));\n  flex-shrink: 0;\n}\n.stock-thumb:not([src]),\n.stock-thumb[src=\"\"] { display: none; }\n";
